package cz.mh.rallye.rallye_backend.templates.application;
import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.util.zip.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import cz.mh.rallye.rallye_backend.identity.application.AuthFailure;import cz.mh.rallye.rallye_backend.templates.domain.StageConfiguration;
import static cz.mh.rallye.rallye_backend.templates.application.TemplateArchive.*;
class TemplateArchiveTest {
 static final Instant AT=Instant.parse("2026-10-29T00:00:00Z");
 static Definition definition(String markdown){return new Definition("Export","Description",-2,Long.MIN_VALUE,List.of(new StageData(1,"Station",60000L,0L,markdown,new StageConfiguration(new StageConfiguration.Gps(true,50d,14d,10d,-1L,2L),new StageConfiguration.Code(true,"YES",null),new StageConfiguration.TimePenalty(true,1000L,Long.MAX_VALUE),new StageConfiguration.Delayed(true,0L,-3L)))));}
 static byte[] archive(){return encode(definition("[Guide](a.md)"),Map.of("a.md","# Guide".getBytes(StandardCharsets.UTF_8)),Map.of("a.md","text/markdown"),AT);}
 static Map<String,byte[]> entries(byte[] zip)throws Exception{var values=new LinkedHashMap<String,byte[]>();try(var in=new ZipInputStream(new ByteArrayInputStream(zip))){for(ZipEntry e;(e=in.getNextEntry())!=null;)values.put(e.getName(),in.readAllBytes());}return values;}
 static byte[] zip(Map<String,byte[]> entries)throws Exception{try(var out=new ByteArrayOutputStream();var z=new ZipOutputStream(out)){for(var e:entries.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}z.finish();return out.toByteArray();}}
 @Test void roundTripPreservesEveryFieldAndInt64WithoutInstallationIds(){var b=decode(archive());assertEquals(definition("[Guide](a.md)"),b.template());assertEquals(Long.MAX_VALUE,b.template().stages().getFirst().configuration().timePenalty().pointsPerInterval());assertEquals(Long.MIN_VALUE,b.template().defaultWrongCodePenaltyPoints());assertEquals(hash(b.files().get("a.md")),b.manifest().files().getFirst().sha256());assertEquals(1,preview(b).fileCount());assertFalse(JSON.writeValueAsString(b.template()).contains("accountId"));}
 @Test void checksumMissingExtraAndUnsupportedVersionFail()throws Exception{for(String mutation:List.of("checksum","missing","extra","version")){var map=entries(archive());switch(mutation){case "checksum"->map.put("files/a.md",new byte[]{1});case "missing"->map.remove("files/a.md");case "extra"->map.put("files/orphan.md",new byte[0]);case "version"->map.put("manifest.json",new String(map.get("manifest.json"),StandardCharsets.UTF_8).replace("\"formatVersion\":1","\"formatVersion\":2").getBytes(StandardCharsets.UTF_8));}assertThrows(AuthFailure.class,()->decode(zip(map)));}}
 @Test void zipSlipAndAbsolutePathsAreRejected()throws Exception{for(String name:List.of("../outside","files/../x.md","files/a/b.md","files/..\\x.md","/etc/passwd","C:/x.md","files/")){var map=entries(archive());map.put(name,new byte[0]);assertThrows(AuthFailure.class,()->decode(zip(map)));}}
 @Test void malformedDuplicateAndCoercedJsonAreRejected()throws Exception{for(String text:List.of("{","null","{}",JSON.writeValueAsString(definition("x")).replace("\"skipPenaltyPoints\":-2","\"skipPenaltyPoints\":1.5"),JSON.writeValueAsString(definition("x")).replace("\"skipPenaltyPoints\":-2","\"skipPenaltyPoints\":\"-2\""),JSON.writeValueAsString(definition("x")).replace("\"name\":\"Export\"","\"name\":\"Export\",\"name\":\"Duplicate\""))){var map=entries(archive());map.put("template.json",text.getBytes(StandardCharsets.UTF_8));assertThrows(AuthFailure.class,()->decode(zip(map)));}}
 @Test void removedStatisticsVersionIsNotExportedOrSilentlyIgnored()throws Exception{
  var map=entries(archive());String text=new String(map.get("template.json"),StandardCharsets.UTF_8);
  assertFalse(text.contains("statisticsVersion"));
  map.put("template.json",text.replace("\"sequenceNo\":1","\"sequenceNo\":1,\"statisticsVersion\":7").getBytes(StandardCharsets.UTF_8));
  assertThrows(AuthFailure.class,()->decode(zip(map)));
 }
 @Test void truncatedArchiveAndChangedCentralDirectoryFail(){var valid=archive();assertThrows(AuthFailure.class,()->decode(Arrays.copyOf(valid,valid.length-1)));var bad=valid.clone();bad[bad.length-6]=0;bad[bad.length-5]=0;bad[bad.length-4]=0;bad[bad.length-3]=0;assertThrows(AuthFailure.class,()->decode(bad));}
 @Test void entryCountAndExpandedMetadataLimitBoundBombs()throws Exception{var many=entries(archive());for(int i=0;i<201;i++)many.put("files/"+i+".md",new byte[0]);assertThrows(AuthFailure.class,()->decode(zip(many)));var expanded=entries(archive());expanded.put("template.json",new byte[MAX_JSON+1]);assertEquals(413,assertThrows(AuthFailure.class,()->decode(zip(expanded))).status());}
 @Test void missingReferencesAndInstallationUrlsAreNotPortable(){assertThrows(AuthFailure.class,()->decode(encode(definition("[Missing](absent.md)"),Map.of(),Map.of(),AT)));for(String link:List.of("/api/v1/race-templates/00000000-0000-0000-0000-000000000000/files/a.md","https://source.test/api/v1/race-templates/00000000-0000-0000-0000-000000000000/files/a.md"))assertThrows(AuthFailure.class,()->decode(encode(definition("[Internal]("+link+")"),Map.of(),Map.of(),AT)));}
 @Test void portableRewritesActualLinksAndReferenceDefinitionsButKeepsCodeAndRelative(){UUID id=UUID.randomUUID();String text="[Guide]("+ImageNames.fileUrl(id,"a.md")+"#part) [relative](b.md) `"+ImageNames.fileUrl(id,"code.md")+"`";String result=InstructionsMarkdown.portable(id,text);assertTrue(result.contains("a.md#part"));assertTrue(result.contains("[relative](b.md)"));assertTrue(result.contains("`"+ImageNames.fileUrl(id,"code.md")+"`"));assertEquals(Set.of("a.md","b.md"),references(result,Set.of("a.md","b.md")));}
 @Test void incompleteDraftIsPreservedButInvalidNumbersAreRejected(){var d=new Definition("Draft",null,0,0,List.of(new StageData(1,null,null,null,null,StageConfiguration.empty())));assertEquals(d,decode(encode(d,Map.of(),Map.of(),AT)).template());var invalid=new Definition("Bad",null,0,0,List.of(new StageData(1,"Bad",-1L,0L,"Text",StageConfiguration.empty())));assertThrows(AuthFailure.class,()->decode(encode(invalid,Map.of(),Map.of(),AT)));}
}
